\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (8\plain \f1\super\lang1033\fs24 rb-va\plain \f1\lang1033\fs24 ) [\plain \f1\b\lang1033\fs24 4 einf\u252 \'fchrende {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Statuten}}\plain \f1\lang1033\fs24 :] \plain \f1\i\lang1033\fs24 >De sacramento prestando ad manutenendum prefatum dominum Franciscum Capitaneum<. >{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Q<Uilibet autem de ciuitate et districtu Mantue teneatur et debeat iurare}}\plain \f1\i\lang1033\fs24  et manutenere predictum dominum Franciscum Capitaneum ... - ... plus et minus arbitrio domini Capitanei.\plain \f1\lang1033\fs24 ;}

