\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -29\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) [\plain \f1\b\lang1033\fs24 Liber I\plain \f1\lang1033\fs24 , 186 Kapitel:] \plain \f1\i\lang1033\fs24 >INcipit liber primus statutorum communis Nouarie. De sacramento potestatis.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 [I]N primis statutum et ordinatum est}}\plain \f1\i\lang1033\fs24 , quod potestas et rector, qui pro tempore fuerit ad regimen ciuitatis Nouarie ... - ... quam fecerint in camera dicti communis peruenire.}

