\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\b\ul\lang1033\fs24 Teil I (Bl. 1-4)\plain \f1\lang1033\fs24  \plain \f1\b\lang1033\fs24 Aus dem Breviarium: {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Proprium de tempore}}\plain \f1\b\lang1033\fs24 , Feria VI. Hebd. III. Quadragesimae bis Feria V. Hebd. IV. Quadragesimae\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 
