\par \pard\fi0\li0\tx915\tx1830\tx2745\tx3660\tx4575\tx5490\tx6405\tx7335\tx8250\tx9165\tx10080\tx10995\tx11910\tx12825\tx13740\tx14655\qj\ri0\sb0\sa0\itap0 (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) [\plain \f1\b\lang1033\fs24 Feria II. Hebdomadae sanctae\plain \f1\lang1033\fs24 , \plain \f1\b\lang1033\fs24 Grad.\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ego autem, dum mihi molesti essent}}\plain \f1\lang1033\fs24 , ... et humiliabam in ieiunio animam me]\plain \f1\i\lang1033\fs24 am: et oracio meam \plain \f1\lang1033\fs24 [in sinu meo convertetur], Vers. \plain \f1\i\lang1033\fs24 >I<{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 udica, Domine, nocentes me}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24 , Off. \plain \f1\i\lang1033\fs24 >C<usto\plain \f1\lang1033\fs24 [di me domine, de manu]\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 peccatoris}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 >Com.<\plain \f1\lang1033\fs24 ;
